patterns.pseudo:
const raw = await load(source);
const valid = validateSchema(raw);
const audit = clean(valid.records, rule);
return {records:audit.kept, excluded:audit.rejected, provenance:{url,sha,readAt,rule}};

pointerdown => capturePointer, dragging=true;
pointermove && dragging => rotate(clamp(delta));
pointerup || pointercancel => release, dragging=false;

before = aggregate(raw);
after = aggregate(clean(raw, rule));
shared = extent([...before,...after].map(d=>d.value));
renderFacets([before,after], shared);

steps = [{id, question, filter, focus, annotation, sources}];
function enterStep(i){apply(steps[i]);}
function explore(){stopScrollHijack();unlockControls();}
